import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the contexts - boring but necessary
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Smartwheels', price: 299.99 }],
    total: 299.99,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - Happy Path (The Fun Way)', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-420-NICE' });
  });

  it('completes full checkout like a speed run', async () => {
    render(<Checkout />);

    // Shipping - fill it fast
    await user.type(screen.getByLabelText(/street address/i), '123 Hiro Protagonist Lane');
    await user.type(screen.getByLabelText(/city/i), 'LA');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment - card goes brrr
    await user.type(screen.getByLabelText(/card number/i), '4242424242424242');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Y.T. Courier');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review and smash that order button
    expect(screen.getByText(/smartwheels/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-420-NICE')).toBeInTheDocument();
    });
  });
});

describe('Validation - Breaking Things On Purpose', () => {
  const user = userEvent.setup();

  it('screams about invalid ZIP like an angry Rat Thing', async () => {
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'YOLO');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByLabelText(/zip/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('rejects garbage card numbers', async () => {
    // Skip to payment step... (abbreviated)
  });
});

describe('Edge Cases - What Could Go Wrong', () => {
  it('shows empty cart message when no items', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure without crashing', async () => {
    mockProcessPayment.mockRejectedValue(new Error('Card declined - nice try'));
    // ... complete flow to review, click place order

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).not.toBeDisabled();
  });
});

describe('Accessibility - Even Kouriers Need This', () => {
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

